Fx1SweepLenB_day_two:
        .byte   $04                     ; 1B78
Fx1SweepLenC_day_two:
        .byte   $02                     ; 1B79

; --------------------------------------------------------------------------
; Frames before the sweep starts
; --------------------------------------------------------------------------
Fx1StartDelay_day_two:
        .byte   $00                     ; 1B7A

; --------------------------------------------------------------------------
; Frames between sweep steps
; --------------------------------------------------------------------------
Fx1SweepRate_day_two:
