; --------------------------------------------------------------------------
; Copy the 23-byte effect record at Y:X into the driver; byte $16 picks the voice.
; --------------------------------------------------------------------------
StartSoundEffect_day_two:
        php                             ; 1BB7
        stx     $10                     ; 1BB8
        sty     $11                     ; 1BBA
        ldy     #$16                    ; 1BBC
        lda     ($10),y                 ; 1BBE
