L1BCC:  sta     Fx1VoiceBits_day_two,x  ; 1BCC
        lda     #$FC                    ; 1BCF
        sta     Fx1EnvPhase_day_two,x   ; 1BD1
        lda     $A1                     ; 1BD4
        and     #$0F                    ; 1BD6
        sta     Fx1Level_day_two,x      ; 1BD8
        dey                             ; 1BDB
        cpx     #$20                    ; 1BDC
