        sta     Fx1FreqLo_day_two,x     ; 1C05
        lda     Fx1StartFreqHi_day_two,x; 1C08
        sta     Fx1FreqHi_day_two,x     ; 1C0B
        plp                             ; 1C0E
        rts                             ; 1C0F

L1C10:  lda     ($10),y                 ; 1C10
        sta     Fx2SweepLen_day_two,y   ; 1C12
        dey                             ; 1C15
        bpl     L1C10                   ; 1C16
