        lda     #$FF                    ; 1C5A
        sta     Fx1EnvPhase_day_two,x   ; 1C5C
        bne     L1CA1                   ; 1C5F
L1C61:  sec                             ; 1C61
        lda     Fx1Level_day_two,x      ; 1C62
        sbc     Fx1ReleaseStep_day_two,x; 1C65
        bcc     L1C74                   ; 1C68
        beq     L1C76                   ; 1C6A
        sta     Fx1Level_day_two,x      ; 1C6C
